  std::string src10 = FUZZ_PARAM_STR();
  if (src10.size() < 10) src10.resize(10, '\0'); else src10.resize(10);
  std::vector<triton::uint8> buf10(10, 0);
  triton::uint80 v80 = triton::utils::cast<triton::uint80>(reinterpret_cast<const triton::uint8*>(src10.data()));
  triton::utils::fromUintToBuffer(v80, buf10.data());
  triton::uint80 back80 = triton::utils::cast<triton::uint80>(buf10.data());
  FUZZ_ASSERT(v80 == back80, "fromUintToBuffer(uint80) round-trip mismatch");

  // ---- uint128: 16-byte buffer round-trip ----
  std::string src16 = FUZZ_PARAM_STR();
  if (src16.size() < 16) src16.resize(16, '\0'); else src16.resize(16);
  std::vector<triton::uint8> buf16(16, 0);
  triton::uint128 v128 = triton::utils::cast<triton::uint128>(reinterpret_cast<const triton::uint8*>(src16.data()));
  triton::utils::fromUintToBuffer(v128, buf16.data());
  triton::uint128 back128 = triton::utils::cast<triton::uint128>(buf16.data());
  FUZZ_ASSERT(v128 == back128, "fromUintToBuffer(uint128) round-trip mismatch");

  // ---- uint256: 32-byte buffer round-trip ----
  std::string src32 = FUZZ_PARAM_STR();
  if (src32.size() < 32) src32.resize(32, '\0'); else src32.resize(32);
  std::vector<triton::uint8> buf32(32, 0);
  triton::uint256 v256 = triton::utils::cast<triton::uint256>(reinterpret_cast<const triton::uint8*>(src32.data()));
  triton::utils::fromUintToBuffer(v256, buf32.data());
  triton::uint256 back256 = triton::utils::cast<triton::uint256>(buf32.data());
  FUZZ_ASSERT(v256 == back256, "fromUintToBuffer(uint256) round-trip mismatch");

  // ---- uint512: 64-byte buffer basic property check ----
  // Avoid FUZZ_PARAM on class types; build a non-zero wide value from smaller primitives when possible.
  std::vector<triton::uint8> buf64(64, 0);
  triton::uint64 lo = *FUZZ_PARAM(triton::uint64);
