  bool any_nonzero = false;
  for (size_t i = 0; i < buf64.size(); ++i) any_nonzero |= (buf64[i] != 0);
  if (static_cast<triton::uint64>(lo | hi) != 0u) {
    FUZZ_ASSERT(any_nonzero, "fromUintToBuffer(uint512) produced all-zero bytes for non-zero value");
  }
}
