// Generate a diverse float input, covering normals, subnormals, NaNs, and infinities
unsigned int sel = *FUZZ_PARAM(unsigned int);
float value = 0.0f;
if ((sel % 5u) == 0u) {
  // Quiet NaN: 0x7FC00000
  uint32_t bits = 0x7FC00000u;
  std::memcpy(&value, &bits, sizeof(bits));
}
else if ((sel % 5u) == 1u) {
  // +Inf: 0x7F800000
  uint32_t bits = 0x7F800000u;
  std::memcpy(&value, &bits, sizeof(bits));
}
else if ((sel % 5u) == 2u) {
  // -Inf: 0xFF800000
  uint32_t bits = 0xFF800000u;
  std::memcpy(&value, &bits, sizeof(bits));
}
else if ((sel % 5u) == 3u) {
  // Subnormal float: exponent=0, nonzero mantissa, random sign
  uint32_t mant = (*FUZZ_PARAM(uint32_t)) & 0x007FFFFFu; // keep mantissa only
  if ((mant & 0x007FFFFFu) == 0u) mant = 1u;             // ensure truly subnormal
  uint32_t sbit = (sel & 1u) ? 0x80000000u : 0u;
  uint32_t bits = sbit | mant;
  std::memcpy(&value, &bits, sizeof(bits));
}
else {
  // Arbitrary finite/NaN/Inf via direct fuzz
  value = *FUZZ_PARAM(float);
}

