uint16_t h = triton::sf::f32_to_f16(value);

// Decode half-precision fields for basic IEEE-754 property checks
uint16_t h_sign = (uint16_t)((h >> 15) & 0x1);
uint16_t h_exp  = (uint16_t)((h >> 10) & 0x1F);
uint16_t h_frac = (uint16_t)(h & 0x03FF);

// Validate IEEE-754 mandated behaviors for special values:
// - NaN must remain NaN in half (exp=all 1s, frac!=0)
// - Infinity must remain infinity with preserved sign (exp=all 1s, frac=0)
if (std::isnan(value)) {
  FUZZ_ASSERT(h_exp == 0x1F && h_frac != 0, "NaN must map to half-precision NaN");
}
if (std::isinf(value)) {
  FUZZ_ASSERT(h_exp == 0x1F && h_frac == 0, "Infinity must map to half-precision infinity");
  int v_sign = std::signbit(value) ? 1 : 0;
  FUZZ_ASSERT(h_sign == v_sign, "Infinity sign must be preserved");
}

