import random
import struct
from typing import List

# Target wants raw bytes used as:
# - instruction opcodes for various ISAs (sizes typically 1..16; AArch64 4; ARM32 2/4; RISC-V 2/4; x86 1..15)
# - concrete memory area buffers (1..128 bytes)
# - exception messages (arbitrary strings)
# Our strategy: produce a compact corpus element that packs multiple slices the fuzzer can consume via FUZZ_PARAM_STR().
# We build a container with several distinct regions concatenated:
# [AArch64 4B][ARM-Thumb 2B][ARM-ARM 4B][RV C 2B][RV std 4B][x86 short 8B][x86 max-ish 15B]
# then several memory payloads of varying sizes (16,32,64,128)
# finally a UTF-8-ish printable segment for messages.
# All segments are valid random bytes; for fixed-width ISAs we use plausible encodings (e.g., known NOPs) mixed with randoms.

A64_NOPS = [b"\x1f\x20\x03\xd5"]  # AArch64 NOP
ARM32_NOPS = [b"\x00\xf0\x20\xe3", b"\x00\xbf"]  # ARM NOP, Thumb NOP
RV_NOPS = [b"\x13\x00\x00\x00",  # ADDI x0,x0,0
           b"\x01\x00"]           # C.NOP (encoding 0x0001 on many toolchains)
X86_NOPS = [b"\x90", b"\x66\x90", b"\x0f\x1f\x00"]


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _pick(rng: random.Random, choices: List[bytes]) -> bytes:
    return rng.choice(choices)


def _mk_aarch64(rng: random.Random) -> bytes:
    # 4-byte fixed
    if rng.random() < 0.5:
        return _pick(rng, A64_NOPS)
    # random 4B
    return _rand_bytes(rng, 4)


def _mk_arm_thumb(rng: random.Random) -> bytes:
    if rng.random() < 0.5:
        return ARM32_NOPS[1]
    return _rand_bytes(rng, 2)


def _mk_arm_arm(rng: random.Random) -> bytes:
    if rng.random() < 0.5:
        return ARM32_NOPS[0]
    return _rand_bytes(rng, 4)


def _mk_rv16(rng: random.Random) -> bytes:
    if rng.random() < 0.5:
        return RV_NOPS[1]
    return _rand_bytes(rng, 2)


def _mk_rv32(rng: random.Random) -> bytes:
    if rng.random() < 0.5:
        return RV_NOPS[0]
    return _rand_bytes(rng, 4)


def _mk_x86_short(rng: random.Random) -> bytes:
    # 1..8 bytes typical
    if rng.random() < 0.5:
        return _pick(rng, X86_NOPS)
    ln = rng.randint(1, 8)
    return _rand_bytes(rng, ln)


def _mk_x86_max(rng: random.Random) -> bytes:
    # up to 15 bytes
    base = _pick(rng, X86_NOPS) if rng.random() < 0.5 else b""
    rest_len = rng.randint(1, 15 - len(base) if len(base) < 15 else 1)
    return (base + _rand_bytes(rng, rest_len))[:15]


def _mk_mem(rng: random.Random, n: int) -> bytes:
    return _rand_bytes(rng, n)


def _mk_printables(rng: random.Random, n: int) -> bytes:
    # produce ASCII-friendly for exception messages
    choices = [ord(c) for c in ("abcdefghijklmnopqrstuvwxyz"
                                "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                                "0123456789 _-.,:;[](){}<>!@#$/+*=\n\t")]
    return bytes(rng.choice(choices) for _ in range(n))


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    chunks: List[bytes] = []

    # Instruction-oriented slices
    chunks.append(_mk_aarch64(rng))     # 4
    chunks.append(_mk_arm_thumb(rng))   # 2
    chunks.append(_mk_arm_arm(rng))     # 4
    chunks.append(_mk_rv16(rng))        # 2
    chunks.append(_mk_rv32(rng))        # 4
    chunks.append(_mk_x86_short(rng))   # 1..8
    chunks.append(_mk_x86_max(rng))     # 1..15

    # Memory payloads
    for sz in (16, 32, 64, 128):
        chunks.append(_mk_mem(rng, sz))

    # Printable message region
    msg_len = rng.randint(16, 96)
    chunks.append(_mk_printables(rng, msg_len))

    # Add a couple of 64-bit addresses for FUZZ_PARAM(uint64)
    for _ in range(4):
        chunks.append(struct.pack('<Q', rng.getrandbits(64)))

    blob = b''.join(chunks)
    # Bound to 4096 bytes
    return blob[:4096]
